script:
// Excel 导出 - 自动宽度配置示例
// 查询数据
var data = db.select("select id, username, email, real_name as '真实姓名', create_time as '创建时间' from sys_user where is_del = 0 limit 10")

// 定义表头映射
var headers = {
    "id": "ID",
    "username": "用户名",
    "email": "邮箱地址",
    "真实姓名": "真实姓名",
    "创建时间": "创建时间"
}

// 创建配置对象，自定义宽度范围
var config = excel.createConfig("自动宽度导出")
config.setHeaderMap(headers)
config.setMinWidth(20)  // 最小列宽 20 字符
config.setMaxWidth(60)  // 最大列宽 60 字符

// 导出为 Excel 并下载
excel.download(data, config)
